import { test } from "node:test";
import assert from "node:assert/strict";

/** RED PHASE — Story 13.3 owns the dark email outbox contract. */
test.skip("[P0][AC1][13.3-UNIT-001] reconciles same-tenant concurrent enqueue and keeps tenant dedupe independent", async () => {
  const { enqueueEmailOutbox } = await import("@/server/email/outbox");
  const deps = createOutboxMemoryHarness();
  const input = { tenantId: "tenant-a", category: "quote.follow_up_due", subjectType: "quote_follow_up", subjectId: "subject-1", period: "2026-09-23", recipient: recipientProjection(), template: { key: "quote-follow-up", version: 1, params: recipientProjection() } };
  const [first, second] = await Promise.all([enqueueEmailOutbox(deps, input), enqueueEmailOutbox(deps, input)]);
  const otherTenant = await enqueueEmailOutbox(deps, { ...input, tenantId: "tenant-b" });
  assert.equal(first.id, second.id);
  assert.notEqual(first.id, otherTenant.id);
  assert.deepEqual(deps.eventsFor(first.id), [{ type: "queued" }]);
  assert.equal(first.state, "queued");
});

test.skip("[P0][AC2][13.3-UNIT-002] claims disjoint rows, uses an injected clock, and applies 5/10/20-minute retry and 15-minute lease rules", async () => {
  const { claimEmailOutbox, recordSyntheticDeliveryOutcome } = await import("@/server/email/outbox");
  const clock = fixedClock("2026-09-23T10:00:00.000Z");
  const deps = createOutboxMemoryHarness({ clock });
  const row = await deps.enqueueEligibleRow();
  const [workerOne, workerTwo] = await Promise.all([claimEmailOutbox(deps, { tenantId: "tenant-a", workerId: "worker-1" }), claimEmailOutbox(deps, { tenantId: "tenant-a", workerId: "worker-2" })]);
  assert.equal(new Set([workerOne?.id, workerTwo?.id]).size, 2);
  assert.equal(workerOne?.leaseExpiresAt, "2026-09-23T10:15:00.000Z");
  await recordSyntheticDeliveryOutcome(deps, { id: row.id, outcome: "retryable_failure" });
  assert.deepEqual(deps.retrySchedule(row.id), ["2026-09-23T10:05:00.000Z", "2026-09-23T10:15:00.000Z", "2026-09-23T10:35:00.000Z"]);
  assert.equal(deps.stateAfterThirdFailure(row.id), "failed");
});

test.skip("[P0][AC3][13.3-UNIT-003] suppresses before a delivery seam and only for matching tenant, recipient hash, and category", async () => {
  const { processDarkEmailOutbox } = await import("@/server/email/outbox");
  const deps = createOutboxMemoryHarness({ deliveryEnabled: false });
  const matching = await deps.enqueueEligibleRow({ recipientHash: "a".repeat(64), category: "quote.follow_up_due" });
  await deps.insertSuppression({ tenantId: "tenant-a", recipientHash: "a".repeat(64), category: "quote.follow_up_due" });
  await processDarkEmailOutbox(deps, { tenantId: "tenant-a" });
  assert.equal(deps.row(matching.id).state, "suppressed");
  assert.deepEqual(deps.eventsFor(matching.id).at(-1), { type: "suppressed" });
  assert.equal(deps.deliverySeamCalls, 0);
});

test.skip("[P0][AC4][13.3-UNIT-004] renders only the recipient entitlement projection and leaves eligible production work queued", async () => {
  const { processDarkEmailOutbox } = await import("@/server/email/outbox");
  const deps = createOutboxMemoryHarness({ deliveryEnabled: false });
  const row = await deps.enqueueEligibleRow({ params: recipientProjection() });
  await processDarkEmailOutbox(deps, { tenantId: "tenant-a" });
  assert.deepEqual(deps.templateInputs, [recipientProjection()]);
  assert.equal(deps.row(row.id).state, "queued");
  assert.equal(deps.deliverySeamCalls, 0);
});

function recipientProjection() { return { recipientUserId: "user-a", displayName: "Ada Elektriker", locale: "sv-SE" }; }
function fixedClock(iso: string) { return { now: () => new Date(iso) }; }
function createOutboxMemoryHarness(_options: Record<string, unknown> = {}) { throw new Error("Story 13.3 RED fixture: implement with server-only outbox dependencies"); }

import { afterAll, beforeAll, describe, expect, test } from "vitest";
import { adminQuery, closeAdminPool } from "../../factories/admin-sql";
import { cleanupFixture, createTwoTenantFixture } from "../../factories/tenants";
import { isLocalStackReachable } from "../../support/test-env";
import { skipUnlessStack } from "../../support/stack-gate";

let stackUp = false;
beforeAll(async () => { stackUp = await isLocalStackReachable(); });
afterAll(async () => { await closeAdminPool(); });

describe("Story 13.3 email outbox database and dark-processor contracts (ATDD RED)", () => {
  test.skip("[P0][AC1][13.3-INT-001] persists one tenant-scoped queued row and one queued event under concurrent dedupe", async (ctx) => {
    if (skipUnlessStack(ctx, stackUp)) return;
    const { enqueueEmailOutbox } = await import("@/server/email/outbox");
    const fixture = await createTwoTenantFixture();
    try {
      const request = outboxRequest(fixture.tenantA.id);
      const results = await Promise.all(Array.from({ length: 6 }, () => enqueueEmailOutbox(request)));
      expect(new Set(results.map((row) => row.id))).toHaveLength(1);
      expect(await adminQuery("select state, count(*)::int as count from public.email_outbox where tenant_id=$1 group by state", [fixture.tenantA.id])).toEqual([{ state: "queued", count: 1 }]);
      expect(await adminQuery("select event_type from public.email_delivery_events where outbox_id=$1", [results[0]!.id])).toEqual([{ event_type: "queued" }]);
    } finally { await cleanupFixture(fixture); }
  });

  test.skip("[P0][AC2][13.3-INT-002] uses PostgreSQL FOR UPDATE SKIP LOCKED for disjoint tenant-explicit claims and recovers one stale lease", async (ctx) => {
    if (skipUnlessStack(ctx, stackUp)) return;
    const { claimEmailOutbox } = await import("@/server/email/outbox");
    const fixture = await createTwoTenantFixture();
    try {
      await seedQueuedRows(fixture.tenantA.id, 2);
      const [one, two] = await Promise.all([claimEmailOutbox({ tenantId: fixture.tenantA.id, workerId: "one" }), claimEmailOutbox({ tenantId: fixture.tenantA.id, workerId: "two" })]);
      expect(one.map((row) => row.id)).not.toEqual(two.map((row) => row.id));
      await expireLease(one[0]!.id);
      expect(await claimEmailOutbox({ tenantId: fixture.tenantA.id, workerId: "three" })).toContainEqual(expect.objectContaining({ id: one[0]!.id, state: "queued" }));
      expect(await deliveryAttemptCount(one[0]!.id)).toBe(0);
    } finally { await cleanupFixture(fixture); }
  });

  test.skip("[P0][AC2][13.3-INT-003] records fixed retry deadlines and a sanitized terminal failure event", async (ctx) => {
    if (skipUnlessStack(ctx, stackUp)) return;
    const { recordSyntheticDeliveryOutcome } = await import("@/server/email/outbox");
    const row = await seedQueuedRow("tenant-a", "2026-09-23T10:00:00.000Z");
    await recordSyntheticDeliveryOutcome({ id: row.id, outcome: "retryable_failure", now: "2026-09-23T10:00:00.000Z" });
    expect(await nextAttemptAt(row.id)).toBe("2026-09-23T10:05:00.000Z");
    await exhaustWithSyntheticFailures(row.id);
    expect(await outboxState(row.id)).toBe("failed");
    expect(await lastEvent(row.id)).toMatchObject({ event_type: "failed", failure_detail: expect.not.stringMatching(/token|password|recipient/i) });
  });

  test.skip("[P0][AC3][13.3-INT-004] atomically changes a matching suppressed queued row before any delivery seam", async (ctx) => {
    if (skipUnlessStack(ctx, stackUp)) return;
    const { processDarkEmailOutbox } = await import("@/server/email/outbox");
    const row = await seedQueuedRow("tenant-a");
    await seedSuppression({ tenantId: "tenant-a", recipientHash: row.recipient_hash, category: row.category });
    await processDarkEmailOutbox({ tenantId: "tenant-a", deliveryEnabled: false });
    expect(await outboxState(row.id)).toBe("suppressed");
    expect(await lastEvent(row.id)).toMatchObject({ event_type: "suppressed" });
  });

  test.skip("[P0][AC4][13.3-INT-005] leaves unsuppressed work queued and writes no provider result, sent event, or delivery attempt", async (ctx) => {
    if (skipUnlessStack(ctx, stackUp)) return;
    const { processDarkEmailOutbox } = await import("@/server/email/outbox");
    const row = await seedQueuedRow("tenant-a");
    await processDarkEmailOutbox({ tenantId: "tenant-a", deliveryEnabled: false });
    expect(await outboxState(row.id)).toBe("queued");
    expect(await adminQuery("select * from public.email_delivery_events where outbox_id=$1 and event_type in ('sending','sent','failed')", [row.id])).toEqual([]);
  });
});

function outboxRequest(tenantId: string) { return { tenantId, category: "quote.follow_up_due", subjectType: "quote_follow_up", subjectId: "subject-13-3", period: "2026-09-23", recipient: { recipientUserId: "user-13-3", displayName: "Ada", locale: "sv-SE" }, template: { key: "quote-follow-up", version: 1, params: { recipientUserId: "user-13-3", displayName: "Ada", locale: "sv-SE" } } }; }
