import { afterAll, beforeAll, describe, expect, test } from "vitest";
import { createClient } from "@supabase/supabase-js";
import { adminQuery, closeAdminPool } from "../../factories/admin-sql";
import { cleanupFixture, createTwoTenantFixture, makeAuthedServerClient } from "../../factories/tenants";
import { isLocalStackReachable, LOCAL_SUPABASE_ANON_KEY, LOCAL_SUPABASE_URL } from "../../support/test-env";
import { skipUnlessStack } from "../../support/stack-gate";

let stackUp = false;
beforeAll(async () => { stackUp = await isLocalStackReachable(); });
afterAll(async () => { await closeAdminPool(); });

describe("Story 13.3 email outbox forced-RLS and authorization contracts (ATDD RED)", () => {
  test.skip("[P0][AC5][13.3-RLS-001] enrolls all three direct tenant tables with forced RLS, grants, policies, and H4 metadata", async (ctx) => {
    if (skipUnlessStack(ctx, stackUp)) return;
    const rows = await adminQuery("select c.relname, c.relrowsecurity, c.relforcerowsecurity from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('email_outbox','email_delivery_events','email_suppressions') order by c.relname");
    expect(rows).toEqual([
      { relname: "email_delivery_events", relrowsecurity: true, relforcerowsecurity: true },
      { relname: "email_outbox", relrowsecurity: true, relforcerowsecurity: true },
      { relname: "email_suppressions", relrowsecurity: true, relforcerowsecurity: true },
    ]);
    const { TENANT_TABLES } = await import("./tenant-table-inventory");
    expect(TENANT_TABLES).toEqual(expect.arrayContaining(["email_outbox", "email_delivery_events", "email_suppressions"]));
  });

  test.skip("[P0][AC5][13.3-RLS-002] blocks direct outbox writes, cross-tenant reads, event mutation, and non-admin queue reads", async (ctx) => {
    if (skipUnlessStack(ctx, stackUp)) return;
    const fixture = await createTwoTenantFixture();
    try {
      const adminA = await makeAuthedServerClient(fixture.adminA);
      const outbox = await seedOutbox(fixture.tenantA.id);
      expect((await adminA.from("email_outbox").insert(forgedOutbox(fixture.tenantA.id))).error?.code).toBe("42501");
      expect((await adminA.from("email_outbox").select("id").eq("tenant_id", fixture.tenantB.id)).data ?? []).toEqual([]);
      expect((await adminA.from("email_delivery_events").update({ event_type: "sent" }).eq("outbox_id", outbox.id)).error?.code).toBe("42501");
      const { readEmailOutboxQueue } = await import("@/server/read-models/email-outbox");
      await expect(readEmailOutboxQueue({ roles: ["saljare"] }, { client: adminA as never })).resolves.toMatchObject({ error: { code: "FORBIDDEN" } });
    } finally { await cleanupFixture(fixture); }
  });

  test.skip("[P0][AC3][13.3-RLS-003] keeps suppression scoped by tenant plus recipient hash plus category", async (ctx) => {
    if (skipUnlessStack(ctx, stackUp)) return;
    const fixture = await createTwoTenantFixture();
    try {
      const suppressedA = await seedOutbox(fixture.tenantA.id, { recipientHash: "a".repeat(64), category: "quote.follow_up_due" });
      const differentCategory = await seedOutbox(fixture.tenantA.id, { recipientHash: "a".repeat(64), category: "other" });
      const tenantB = await seedOutbox(fixture.tenantB.id, { recipientHash: "a".repeat(64), category: "quote.follow_up_due" });
      await seedSuppression(fixture.tenantA.id, "a".repeat(64), "quote.follow_up_due");
      const { processDarkEmailOutbox } = await import("@/server/email/outbox");
      await processDarkEmailOutbox({ tenantId: fixture.tenantA.id, deliveryEnabled: false });
      expect(await outboxState(suppressedA.id)).toBe("suppressed");
      expect(await outboxState(differentCategory.id)).toBe("queued");
      expect(await outboxState(tenantB.id)).toBe("queued");
    } finally { await cleanupFixture(fixture); }
  });

  test.skip("[P1][AC5][13.3-RLS-004] gives anon no table access and prevents recipient/body/detail disclosure from Admin queue rows", async (ctx) => {
    if (skipUnlessStack(ctx, stackUp)) return;
    const anon = createClient(LOCAL_SUPABASE_URL, LOCAL_SUPABASE_ANON_KEY, { auth: { autoRefreshToken: false, persistSession: false } });
    expect((await anon.from("email_outbox").select("id")).data ?? []).toEqual([]);
    const { readEmailOutboxQueue } = await import("@/server/read-models/email-outbox");
    const projection = await readEmailOutboxQueue({ roles: ["tenant_admin"] });
    expect(JSON.stringify(projection.data)).not.toMatch(/recipient|template_body|failure_detail/i);
    expect(JSON.stringify(projection.data)).not.toMatch(/activation|send now/i);
  });
});

async function seedOutbox(_tenantId: string, _overrides: Record<string, string> = {}): Promise<{ id: string }> { throw new Error("Story 13.3 RED fixture"); }
function forgedOutbox(tenantId: string) { return { tenant_id: tenantId, recipient_hash: "b".repeat(64), category: "quote.follow_up_due", subject_type: "quote_follow_up", subject_id: crypto.randomUUID(), logical_period: "2026-09-23", template_key: "quote-follow-up", template_version: 1, template_params: {} }; }
async function seedSuppression(_tenantId: string, _recipientHash: string, _category: string): Promise<void> { throw new Error("Story 13.3 RED fixture"); }
async function outboxState(_id: string): Promise<string> { throw new Error("Story 13.3 RED fixture"); }

import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, mkdirSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

/** RED PHASE — provider SDKs, credentials, public paths, and client reachability are forbidden before Story 13.4. */
test.skip("[P0][AC4][13.3-GUARD-001] rejects email-provider SDK imports and credential references in runtime source", async () => {
  const { scanEmailProviderContainment } = await import("../../../../scripts/verify/check-service-role-containment.mjs");
  const root = mkdtempSync(join(tmpdir(), "elpro-email-provider-"));
  const server = join(root, "src", "server", "email");
  mkdirSync(server, { recursive: true });
  writeFileSync(join(server, "provider.ts"), "import { Resend } from 'resend'; const key = process.env.RESEND_API_KEY;");
  const result = scanEmailProviderContainment(root);
  assert.ok(result.violations.some((violation: string) => /provider|credential|resend/i.test(violation)));
});

test.skip("[P0][AC4][13.3-GUARD-002] rejects any alternate email API route or a client-reachable outbox/service import", async () => {
  const { scanEmailProviderContainment } = await import("../../../../scripts/verify/check-service-role-containment.mjs");
  const root = mkdtempSync(join(tmpdir(), "elpro-email-route-"));
  const route = join(root, "src", "app", "api", "email", "send");
  const client = join(root, "src", "components");
  mkdirSync(route, { recursive: true }); mkdirSync(client, { recursive: true });
  writeFileSync(join(route, "route.ts"), "import { processDarkEmailOutbox } from '@/server/email/outbox'; export async function POST() {}");
  writeFileSync(join(client, "outbox.tsx"), "'use client'; import { processDarkEmailOutbox } from '@/server/email/outbox';");
  assert.equal(scanEmailProviderContainment(root).violations.length, 2);
});

test.skip("[P1][AC4][13.3-GUARD-003] allows the sole authenticated jobs route to import a server-only dark processor without a provider call path", async () => {
  const { scanEmailProviderContainment } = await import("../../../../scripts/verify/check-service-role-containment.mjs");
  const root = mkdtempSync(join(tmpdir(), "elpro-email-jobs-"));
  const route = join(root, "src", "app", "api", "jobs", "run");
  const outbox = join(root, "src", "server", "email");
  mkdirSync(route, { recursive: true }); mkdirSync(outbox, { recursive: true });
  writeFileSync(join(route, "route.ts"), "import { processDarkEmailOutbox } from '@/server/email/outbox';");
  writeFileSync(join(outbox, "outbox.ts"), "export async function processDarkEmailOutbox() { return { state: 'queued' }; }");
  assert.deepEqual(scanEmailProviderContainment(root).violations, []);
});
